#!/usr/bin/env python3
"""Generate the skill tables in AGENTS.md and .github/copilot-instructions.md.

Both tables come from the `name` and `description` frontmatter of every
skills/<name>/SKILL.md, so they can never drift from the skills themselves.

    python3 .github/scripts/skill_table.py           # rewrite the tables
    python3 .github/scripts/skill_table.py --check   # exit 1 if a table is stale

Each table lives between two marker comments; everything outside the markers is
hand-written and left untouched.
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SKILLS = ROOT / "skills"

START = "<!-- skill-table:start (generated by .github/scripts/skill_table.py; do not edit) -->"
END = "<!-- skill-table:end -->"

# Files that carry a generated skill table.
TARGETS = [ROOT / "AGENTS.md", ROOT / ".github" / "copilot-instructions.md"]


def read_frontmatter(skill_md: Path) -> dict[str, str]:
    """Return the top-level scalar keys of a SKILL.md frontmatter block.

    Folded (`>-`, `>`) and literal (`|`) scalars are joined into one line. Nested
    mappings such as `metadata:` are skipped. Standard library only, like the
    validator, so CI needs no install step.
    """
    text = skill_md.read_text(encoding="utf-8")
    if not text.startswith("---\n"):
        return {}
    end = text.find("\n---\n", 3)
    if end == -1:
        return {}

    data: dict[str, str] = {}
    key: str | None = None
    folded = False
    for raw in text[4:end].split("\n"):
        if raw.startswith((" ", "\t")):
            if key and folded:
                data[key] = (data[key] + " " + raw.strip()).strip()
            continue
        if ":" not in raw or raw.lstrip().startswith("#"):
            key, folded = None, False
            continue
        k, _, v = raw.partition(":")
        key, v = k.strip(), v.strip()
        if v in {">", ">-", "|", "|-"}:
            data[key], folded = "", True
        elif v == "":
            key, folded = None, False  # nested mapping such as metadata:
        else:
            data[key], folded = v.strip("\"'"), False
    return data


def skills() -> list[tuple[str, str]]:
    rows = []
    for skill_dir in sorted(p for p in SKILLS.iterdir() if p.is_dir()):
        skill_md = skill_dir / "SKILL.md"
        if not skill_md.is_file():
            continue
        fm = read_frontmatter(skill_md)
        rows.append((skill_dir.name, " ".join(fm.get("description", "").split())))
    return rows


def render() -> str:
    lines = [START, "", "| Skill | What it does and when to use it |", "| --- | --- |"]
    for name, description in skills():
        cell = description.replace("|", "\\|")
        lines.append(f"| `{name}` | {cell} |")
    lines += ["", END]
    return "\n".join(lines)


def apply(text: str, table: str, path: Path) -> str:
    start, end = text.find(START), text.find(END)
    if start == -1 or end == -1 or end < start:
        raise SystemExit(
            f"{path.relative_to(ROOT)}: skill-table markers not found. "
            f"Add the two marker lines where the table should go:\n{START}\n{END}"
        )
    return text[:start] + table + text[end + len(END):]


def stale_files() -> list[Path]:
    """Files whose generated table differs from the skills on disk."""
    table = render()
    return [p for p in TARGETS if apply(p.read_text(encoding="utf-8"), table, p) != p.read_text(encoding="utf-8")]


def main() -> int:
    if "--check" in sys.argv:
        stale = stale_files()
        for p in stale:
            print(f"{p.relative_to(ROOT)}: skill table is stale. Run python3 .github/scripts/skill_table.py")
        return 1 if stale else 0

    table = render()
    for p in TARGETS:
        old = p.read_text(encoding="utf-8")
        new = apply(old, table, p)
        if new != old:
            p.write_text(new, encoding="utf-8")
            print(f"Updated {p.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
